const refs=slugs=>'<div class="review-refs-inline">'+slugs.map(slug=>{const s=data.sources.find(s=>s.slug===slug);return s?'<a href="#ref-'+esc(slug)+'">'+esc(sourceLabel(s))+'</a>':''}).join('')+'</div>';
