 '<section class="folio-section" id="practice-cases">'+head('05','cases-title','cases','caseIntro')+'<div class="review-evidence-key">'+['field','model','programme','theory'].map(k=>'<span data-kind="'+k+'">'+esc(w(k==='theory'?'theoryKey':k))+'</span>').join('')+'</div><div class="review-cases">'+v.cases.map(c=>'<article class="review-case"><div class="case-place"><span>'+esc(text(c.city))+' / '+esc(text(c.region))+'</span><span>'+esc(w(c.kind))+'</span></div><h3 id="case-'+c.id+'">'+esc(text(c.title))+'</h3><p class="mechanism">'+esc(text(c.mechanism))+'</p><dl><dt>'+esc(w('evidence'))+'</dt><dd>'+esc(text(c.evidence))+'</dd><dt>'+esc(w('transfer'))+'</dt><dd>'+esc(text(c.transfer))+'</dd></dl>'+refs(c.refs)+'</article>').join('')+'</div></section>'+
 '<section class="folio-section" id="shared-terms">'+head('06','terms-title','glossary','glossaryIntro')+'<div class="review-glossary">'+v.glossary.map(c=>'<details><summary>'+esc(c.term)+'</summary><p>'+esc(text(c.definition))+'</p></details>').join('')+'</div></section>'+
 '<section class="folio-section" id="team-discussion">'+head('07','discussion-title','discussion','discussionIntro')+'<div class="review-discussion">'+v.discussion.map(c=>'<article><h3>'+esc(text(c.title))+'</h3><p>'+esc(text(c.body))+'</p></article>').join('')+'</div><div class="review-actions"><a href="team.html">'+esc(w('team'))+' →</a><a href="'+report+'">'+esc(w('report'))+'</a></div></section>'+
 '<section class="folio-section" id="review-references">'+head('08','references-title','references','referencesIntro')+'<ol class="review-source-list" data-outline-ignore>'+data.sources.map(s=>{const role=s.slug==='brief-2026'?'briefRole':s.role==='course'?'courseRole':s.role==='cases'?'caseRole':'methodRole';const loc=s.locators||s.actual_read_scope?.locators||[];return '<li class="review-source" id="ref-'+esc(s.slug)+'"><h3><a href="'+esc(s.official_url)+'" target="_blank" rel="noopener">'+esc(s.title)+'</a></h3><p>'+esc((s.authors||[]).join('; '))+' · '+esc(s.year??'n.d.')+'</p><p class="source-scope">'+esc(w(role))+' · '+esc(w('read'))+': '+esc(w(s.read_scope))+'</p>'+(loc.length?'<details><summary>'+esc(w('detail'))+'</summary><p>'+esc(Array.isArray(loc)?loc.join(' · '):loc)+'</p></details>':'')+'</li>';}).join('')+'</ol></section>';
 root.querySelectorAll('[data-track-filter]').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('[data-track-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));root.querySelectorAll('[data-track-group]').forEach(x=>x.hidden=b.dataset.trackFilter!=='all'&&x.dataset.trackGroup!==b.dataset.trackFilter);}));
